#include <stdio.h>
int next(void) { static int n = 10; return n++; }
int main(void) {
    int a[] = {4, 8, 12}, *p = a;
    int x = *p++ + 1;
    int y = 7 / 2 * 2 + 7 % 2;
    int first = next();
    printf("%d %d %d|", x, *p, y);
    printf("%3d|%-3d|%.2f|", first, next(), 5 / 2.0);
    printf("%c%c\n", 'A' + 2, 97);
    return 0;
}

#include <iostream>
using namespace std;
struct M { M() { cout << "M "; } ~M() { cout << "~M "; } };
struct B {
    B() { cout << "B "; }
    virtual ~B() { cout << "~B "; }
    virtual void who() const { cout << "B.who "; }
};
struct D : B {
    M m;
    D() { cout << "D "; }
    ~D() { cout << "~D "; }
    void who() const override { cout << "D.who "; }
};
int main() { B *p = new D; p->who(); p->B::who(); delete p; }

