What is the output of the following C program?

#include <stdio.h>
#include <string.h>
int pal(const char *l, const char *r) {
    if (l >= r)
        return 1;
    return *l == *r && pal(l + 1, r - 1);
}
int main(void) {
    const char *a = "level", *b = "lever";
    printf("%d %d", pal(a, a + strlen(a) - 1), pal(b, b + strlen(b) - 1));
    return 0;
}

What is the output of the following C program?

