void f(int *a, int n) {
    if (n <= 1)
        return;
    int t = a[0]; a[0] = a[n - 1]; a[n - 1] = t;
    f(a + 1, n - 2);
}
int main(void) {
    int a[] = {1, 2, 3, 4, 5, 6};
    f(a + 1, 4);
    for (int i = 0; i < 6; i++)
        printf("%d", a[i]);
    return 0;
}

